"""Program 4: Fibonacci Sequence
Generates the Fibonacci sequence up to n terms."""
def fibonacci(n):
    seq = [0, 1]
    for i in range(2, n):
        seq.append(seq[-1] + seq[-2])
    return seq[:n]

def main():
    n = int(input("Enter number of terms: "))
    print(fibonacci(n))

if __name__ == "__main__":
    main()

"""Program 5: Palindrome Checker
Checks if a string reads the same forwards and backwards."""
def is_palindrome(s):
    cleaned = s.lower().replace(" ", "")
    return cleaned == cleaned[::-1]

def main():
    s = input("Enter a string: ")
    if is_palindrome(s):
        print(f'"{s}" is a palindrome')
    else:
        print(f'"{s}" is not a palindrome')

if __name__ == "__main__":
    main()

"""Program 6: Prime Number Checker
Checks if a number is prime."""
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def main():
    n = int(input("Enter a number: "))
    if is_prime(n):
        print(f"{n} is a prime number")
    else:
        print(f"{n} is not a prime number")

if __name__ == "__main__":
    main()

"""Program 7: Factorial Calculator
Computes factorial using both recursion and iteration."""
def factorial_recursive(n):
    if n <= 1:
        return 1
    return n * factorial_recursive(n - 1)

def factorial_iterative(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def main():
    n = int(input("Enter a number: "))
    print(f"Recursive: {factorial_recursive(n)}")
    print(f"Iterative: {factorial_iterative(n)}")

if __name__ == "__main__":
    main()

"""Program 8: Reverse a String
Reverses a string using slicing and a manual loop."""
def reverse_slice(s):
    return s[::-1]

def reverse_manual(s):
    rev = ""
    for ch in s:
        rev = ch + rev
    return rev

def main():
    s = input("Enter a string: ")
    print(f"Slicing: {reverse_slice(s)}")
    print(f"Manual:  {reverse_manual(s)}")

if __name__ == "__main__":
    main()

