"""Program 17: Armstrong Number Checker
Checks if a number is an Armstrong number."""
def is_armstrong(n):
    digits = [int(d) for d in str(n)]
    power = len(digits)
    return sum(d ** power for d in digits) == n

def main():
    n = int(input("Enter a number: "))
    if is_armstrong(n):
        print(f"{n} is an Armstrong number")
    else:
        print(f"{n} is not an Armstrong number")

if __name__ == "__main__":
    main()

"""Program 18: GCD and LCM Calculator
Computes the greatest common divisor and least common multiple."""
def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b) if a and b else 0

def main():
    a = int(input("Enter first number: "))
    b = int(input("Enter second number: "))
    print(f"GCD: {gcd(a, b)}")
    print(f"LCM: {lcm(a, b)}")

if __name__ == "__main__":
    main()

"""Program 19: Star Pyramid Pattern
Prints a pyramid of stars of height n."""
def pyramid(n):
    for i in range(1, n + 1):
        spaces = " " * (n - i)
        stars = "*" * (2 * i - 1)
        print(spaces + stars)

def main():
    n = int(input("Enter pyramid height: "))
    pyramid(n)

if __name__ == "__main__":
    main()

"""Program 20: Number Guessing Game
The computer picks a random number and you try to guess it."""
import random

def main():
    secret = random.randint(1, 100)
    attempts = 0
    print("Guess a number between 1 and 100!")
    while True:
        guess = int(input("Your guess: "))
        attempts += 1
        if guess < secret:
            print("Too low!")
        elif guess > secret:
            print("Too high!")
        else:
            print(f"Correct! You guessed it in {attempts} attempts.")
            break

if __name__ == "__main__":
    main()
